<?php $this->assign('title','Apontamentos recebidos'); ?>
<div class="page-heading"><h1>Apontamentos recebidos</h1><?= $this->Html->link('Todas as atividades / O.S.',['controller'=>'Atividades','action'=>'index'],['class'=>'btn btn-outline-secondary']) ?></div>
<p class="text-secondary">Horas e insumos pendentes por O.S., por ordem de recebimento. Confirmação de lançamento manual no TOTVS.</p>
<section class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>O.S.</th><th>Descrição / equipamento</th><th>Setor</th><th>Apontamentos pendentes</th><th>Insumos pendentes</th><th>Horas pendentes</th><th>Primeiro recebido</th><th>Ação</th></tr></thead><tbody>
